    return n;
}

int main() {
    printf("%d\n", fact(5));
    return 0;
}

answer:
#include <stdio.h>

int fact(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * fact(n - 1);
}

int main() {
    printf("%d\n", fact(5));
    return 0;
}

